{
  "capability": "customs-trade-compliance",
  "version": "1.0.0",
  "scenarios": [
    {
      "id": "CTC-001",
      "name": "Standard tariff classification of a consumer electronics product",
      "difficulty": "easy",
      "category": "tariff-classification",
      "context": {
        "situation": "Your company is importing 5,000 units of a portable Bluetooth speaker (model SoundWave 360) from a manufacturer in Shenzhen, China. The speaker weighs 450g, has a built-in rechargeable lithium battery, connects via Bluetooth 5.3, includes a 3.5mm aux input, and has a waterproof rating of IPX7. It has no other function — no voice assistant, no radio, no speakerphone capability. The unit cost is $18.50 FOB Shenzhen. Your customs broker has asked for classification instructions.",
        "available_data": {
          "product": "Portable Bluetooth speaker (SoundWave 360)",
          "manufacturer": "Shenzhen AudioTech Co., Ltd",
          "country_of_origin": "China",
          "unit_cost_fob": 18.50,
          "currency": "USD",
          "quantity": 5000,
          "total_value_fob": 92500,
          "weight_per_unit_g": 450,
          "material_composition": "ABS plastic housing (60%), speaker driver (25%), lithium battery (10%), PCB/electronics (5%)",
          "primary_function": "Sound reproduction via wireless Bluetooth connection",
          "secondary_functions": "None — single-function speaker",
          "destination_port": "Los Angeles/Long Beach",
          "incoterm": "FOB Shenzhen"
        }
      },
      "task": "Classify this product under the US Harmonized Tariff Schedule, explain your GRI analysis, and provide the duty rate. Also identify any additional duties (e.g., Section 301) that may apply given the country of origin.",
      "evaluation_criteria": [
        {
          "criterion": "correct_classification",
          "weight": 0.35,
          "rubric": {
            "pass": "Classifies under heading 8518 (loudspeakers) — specifically HTS 8518.22 (multiple loudspeakers mounted in the same enclosure) or 8518.29 (other loudspeakers). Explains that GRI 1 resolves classification because heading 8518 specifically covers loudspeakers, and the Bluetooth connectivity is the means of signal transmission, not a separate function. Notes that this is NOT an ADP machine (8471) because it fails the four criteria in Section XVI Note 5(A).",
            "fail": "Classifies under 8527 (reception apparatus for radio) or 8471 (ADP machines) or 8519 (sound recording/reproducing). Does not apply GRI 1 first. Fails to distinguish between a speaker (8518) and a radio receiver (8527)."
          }
        },
        {
          "criterion": "duty_rate_and_additional_duties",
          "weight": 0.30,
          "rubric": {
            "pass": "Identifies the MFN duty rate for the specific subheading (typically 4.9% for 8518.22 or free for 8518.29). Correctly identifies that Chinese-origin goods under heading 8518 are subject to Section 301 List 3 additional tariff of 25%. Calculates total effective duty rate. Notes that the duty base is the transaction value adjusted from FOB to include freight and insurance to the US port.",
            "fail": "States only the MFN rate without mentioning Section 301. Gets the duty rate wrong. Does not mention that the customs value must be adjusted from FOB to include ocean freight and insurance for US entry."
          }
        },
        {
          "criterion": "classification_rationale",
          "weight": 0.35,
          "rubric": {
            "pass": "Walks through GRI 1 systematically: identifies Chapter 85 as the relevant chapter, checks Section XVI notes (particularly Note 3 for composite machines — not applicable here because the speaker has a single function), confirms heading 8518 covers the product. Notes that the lithium battery and Bluetooth module are integral components, not separate articles. Mentions checking the CBP CROSS database for prior rulings on Bluetooth speakers.",
            "fail": "Provides classification without explanation. Does not reference GRI. Does not check Section XVI notes. Treats the Bluetooth module or battery as creating a multi-function device requiring essential character analysis."
          }
        }
      ]
    },
    {
      "id": "CTC-002",
      "name": "Selecting the correct Incoterm for a containerised ocean shipment",
      "difficulty": "easy",
      "category": "incoterms",
      "context": {
        "situation": "Your company is negotiating a purchase of industrial valves from a supplier in Hamburg, Germany. The shipment will move by ocean container (1×40' HC) from Hamburg to the Port of Houston. The supplier has proposed FOB Hamburg. Your logistics team has asked the trade compliance team to review the Incoterm selection. The total order value is €85,000. You need to advise on whether FOB is appropriate and what the customs valuation implications are.",
        "available_data": {
          "product": "Industrial stainless steel valves (various sizes)",
          "supplier": "Hamburg Valve GmbH",
          "origin": "Germany",
          "destination": "Houston, TX warehouse",
          "transport_mode": "Ocean container (1×40' HC)",
          "proposed_incoterm": "FOB Hamburg",
          "order_value_eur": 85000,
          "ocean_freight_estimate_usd": 3200,
          "marine_insurance_estimate_usd": 425,
          "inland_freight_houston_to_warehouse_usd": 850,
          "us_duty_rate": "2.0%",
          "exchange_rate_eur_usd": 1.09
        }
      },
      "task": "Advise on the Incoterm selection, explain why FOB may not be the best choice for containerised cargo, and calculate the US customs value under the proposed terms.",
      "evaluation_criteria": [
        {
          "criterion": "incoterm_analysis",
          "weight": 0.40,
          "rubric": {
            "pass": "Identifies that FOB is technically incorrect for containerised ocean freight under Incoterms 2020. Explains that FOB transfers risk at the ship's rail, but for containers, the goods are delivered to the container terminal before loading — the relevant risk transfer point is the container yard, not the ship's rail. Recommends FCA Hamburg (seller's obligation ends when goods are handed to the carrier at the named place) or CIF/CIP Houston depending on who should arrange freight and insurance.",
            "fail": "Accepts FOB for containerised cargo without comment. Does not mention the Incoterms 2020 guidance that FOB, CFR, and CIF are intended for bulk/break-bulk cargo, not containers. Confuses risk transfer with cost transfer."
          }
        },
        {
          "criterion": "customs_valuation",
          "weight": 0.35,
          "rubric": {
            "pass": "Correctly calculates the US customs value. Under FOB/FCA terms, the US customs value must include ocean freight and insurance (the US values on a CIF-equivalent basis — 19 CFR § 152.103). Calculation: €85,000 × 1.09 = $92,650 + $3,200 freight + $425 insurance = $96,275 customs value. Duty: $96,275 × 2.0% = $1,925.50. Notes that inland freight from Houston port to the warehouse is NOT included in customs value.",
            "fail": "Uses the invoice value (€85,000 or $92,650) as the customs value without adding freight and insurance. Does not know that US customs values on a CIF-equivalent basis. Includes inland freight in the customs value."
          }
        },
        {
          "criterion": "practical_recommendation",
          "weight": 0.25,
          "rubric": {
            "pass": "Provides a practical recommendation considering the business context. Notes that FCA with the buyer arranging freight gives the buyer more control over the shipping line, routing, and insurance coverage. Alternatively, CIP Houston shifts the freight arrangement to the seller — appropriate if the German supplier has better ocean freight rates. Mentions that CIP 2020 requires ICC(A) all-risks coverage, which may be more expensive than what the buyer would arrange independently.",
            "fail": "Provides no practical recommendation. Does not consider who has better freight rates or more logistics capability. Does not mention the insurance requirements difference between CIF (ICC C minimum) and CIP (ICC A minimum) under Incoterms 2020."
          }
        }
      ]
    },
    {
      "id": "CTC-003",
      "name": "Basic import documentation checklist for a first-time importer",
      "difficulty": "easy",
      "category": "documentation",
      "context": {
        "situation": "A small US company is importing goods for the first time — 200 cartons of ceramic dinnerware sets from a factory in Jingdezhen, China, valued at $28,000 CIF Los Angeles. The company has obtained an importer of record number but has never filed an entry before. They have engaged a customs broker and need to know what documents to provide. The shipment is arriving by ocean in 10 days.",
        "available_data": {
          "product": "Ceramic dinnerware sets (plates, bowls, mugs)",
          "hs_code_expected": "6912.00 (ceramic tableware)",
          "origin": "China",
          "destination_port": "Los Angeles",
          "incoterm": "CIF Los Angeles",
          "declared_value_cif": 28000,
          "cartons": 200,
          "total_weight_kg": 4800,
          "transport_mode": "Ocean FCL (1×20')",
          "vessel_eta": "10 days from today",
          "ior_number": "Obtained",
          "customs_broker": "Engaged",
          "first_time_importer": true,
          "duty_rate": "9.8%",
          "section_301_applicable": true,
          "section_301_rate": "7.5%"
        }
      },
      "task": "Provide a complete list of required documents for this import entry, explain the ISF filing requirement and its timeline, and identify any PGA (Partner Government Agency) requirements for ceramic dinnerware.",
      "evaluation_criteria": [
        {
          "criterion": "document_list",
          "weight": 0.35,
          "rubric": {
            "pass": "Lists all required documents: commercial invoice (conforming to 19 CFR § 141.86), packing list (carton count, weight, dimensions, marks/numbers), ocean bill of lading, entry summary (CBP 7501 — broker will prepare), customs bond (continuous or single-entry — first-time importers often need a single-entry bond until volume justifies a continuous bond), and arrival notice from the shipping line. Notes that the broker will need a power of attorney from the importer.",
            "fail": "Misses critical documents (no mention of customs bond, no mention of ISF, no mention of power of attorney). Lists documents that are not required (e.g., export licence for uncontrolled consumer goods). Does not mention the commercial invoice requirements under 19 CFR § 141.86."
          }
        },
        {
          "criterion": "isf_requirements",
          "weight": 0.30,
          "rubric": {
            "pass": "Explains the ISF 10+2 requirement: must be filed 24 hours BEFORE vessel loading at the foreign port (not 24 hours before arrival). Lists the 10 importer data elements (manufacturer name/address, seller, buyer, ship-to, country of origin, HS-6, container stuffing location, consolidator, IOR number, consignee number). Notes that late or inaccurate ISF triggers $5,000 liquidated damages per violation. With ETA in 10 days, the ISF may already need to be filed or filed very soon depending on when the vessel loads.",
            "fail": "Says ISF is filed 24 hours before arrival (wrong — it's before loading at origin). Lists fewer than 5 of the 10 data elements. Does not mention the $5,000 penalty for late filing. Does not flag the urgency given the 10-day ETA."
          }
        },
        {
          "criterion": "pga_requirements",
          "weight": 0.35,
          "rubric": {
            "pass": "Identifies FDA as the relevant PGA for ceramic tableware. Ceramicware is subject to FDA's lead and cadmium testing requirements (CPSC regulates children's products; FDA regulates food-contact ceramicware under 21 CFR § 109.16). Notes that FDA may detain ceramicware from China for testing — Chinese-origin ceramics have a higher detention rate. Advises obtaining a test report from an FDA-recognised lab showing compliance with lead/cadmium leaching limits before shipment arrives. Mentions that FDA prior notice may be required if the ceramicware is considered a 'food-contact surface.'",
            "fail": "Does not mention FDA at all. Says 'no PGA requirements' for ceramicware. Confuses CPSC with FDA jurisdiction for food-contact ceramics. Does not mention lead/cadmium testing requirements."
          }
        }
      ]
    },
    {
      "id": "CTC-004",
      "name": "Straightforward restricted party screening false positive adjudication",
      "difficulty": "easy",
      "category": "restricted-party-screening",
      "context": {
        "situation": "Your screening software has flagged a new customer order. The customer is 'Al-Hassan Trading Company, 47 Industrial Zone Road, Amman, Jordan.' The screening tool returned a 78% name match against 'AL-HASSAN, Ahmed Ibrahim,' an individual on the OFAC SDN list with a listed address in Damascus, Syria. The order is for $12,000 worth of industrial water filtration equipment (EAR99 — no export control classification). The customer has been in business since 2004, has a Jordanian commercial registration, and has purchased from your company twice before (2021, 2023) without issue.",
        "available_data": {
          "customer_name": "Al-Hassan Trading Company",
          "customer_address": "47 Industrial Zone Road, Amman, Jordan",
          "customer_type": "Established trading company, incorporated 2004",
          "customer_registration": "Jordanian Ministry of Industry and Trade — Reg# JO-IND-2004-3847",
          "prior_orders": ["2021-06: $8,500 (shipped without issue)", "2023-03: $11,200 (shipped without issue)"],
          "screening_hit": {
            "list": "OFAC SDN",
            "listed_name": "AL-HASSAN, Ahmed Ibrahim",
            "listed_address": "Damascus, Syria",
            "listed_type": "Individual",
            "match_score_percent": 78,
            "match_type": "Partial name — surname match",
            "listed_dob": "1972-03-15",
            "listed_nationality": "Syrian"
          },
          "product": "Industrial water filtration equipment",
          "eccn": "EAR99",
          "order_value_usd": 12000
        }
      },
      "task": "Adjudicate this screening hit. Determine whether it is a false positive or requires further investigation. Document your reasoning and disposition.",
      "evaluation_criteria": [
        {
          "criterion": "adjudication_analysis",
          "weight": 0.40,
          "rubric": {
            "pass": "Correctly identifies this as a likely false positive based on multiple distinguishing factors: (1) the screened entity is a company, the listed entity is an individual, (2) the address is Jordan vs Syria — different countries, (3) only a surname match at 78% — 'Al-Hassan' is an extremely common Arabic name, (4) the customer has a verifiable Jordanian business registration, (5) two prior clean transactions. Notes that 78% is below the typical threshold for serious concern (85%+). Documents all factors systematically.",
            "fail": "Blocks the transaction based on the 78% match alone without analysing the distinguishing factors. Clears the transaction without documenting any analysis. Does not note the entity-type mismatch (company vs individual). Does not recognise that 'Al-Hassan' is an extremely common name in Arabic-speaking countries."
          }
        },
        {
          "criterion": "documentation_and_process",
          "weight": 0.30,
          "rubric": {
            "pass": "Documents the adjudication with: screening tool and date, all parties screened, hit details, each distinguishing factor analysed, conclusion (false positive), and name/date of the adjudicator. Notes that the adjudication record must be retained for 5 years. Mentions that the disposition should be approved by a compliance officer or manager (not just the analyst who ran the screening).",
            "fail": "Provides a verbal 'it's fine, proceed' without documentation. Does not mention record retention. Does not require supervisory approval of the false positive determination."
          }
        },
        {
          "criterion": "risk_awareness",
          "weight": 0.30,
          "rubric": {
            "pass": "Despite concluding false positive, notes residual risk factors to monitor: Jordan borders Syria (geographic proximity), and the customer is a trading company (trading companies can be intermediaries for diversion). Recommends: verify the end use/end user if the product has any dual-use potential (water filtration equipment is generally benign but certain membrane technologies are controlled). Confirms EAR99 classification means no export licence requirement for Jordan.",
            "fail": "Does not consider any residual risk. Does not mention Jordan's proximity to Syria as a factor worth noting. Does not verify the EAR99 classification. Over-reacts by blocking a clearly distinguishable false positive."
          }
        }
      ]
    },
    {
      "id": "CTC-005",
      "name": "Calculating FTA duty savings under USMCA for an automotive component",
      "difficulty": "easy",
      "category": "fta-qualification",
      "context": {
        "situation": "Your company imports aluminium wheel rims from a Mexican manufacturer. The rims are cast and machined in Monterrey, Mexico. The aluminium alloy ingots used in production are sourced from a Canadian smelter (60% of material cost) and a Russian smelter (40% of material cost). The rims are classified under HTS 8708.70 (wheel parts and accessories for motor vehicles). You want to determine if these rims qualify for USMCA preferential treatment (duty-free) versus the MFN rate of 2.5%.",
        "available_data": {
          "product": "Cast aluminium wheel rims for passenger vehicles",
          "hts_code": "8708.70",
          "manufacturer": "Monterrey Wheels S.A. de C.V.",
          "country_of_manufacture": "Mexico",
          "unit_fob_price_usd": 95.00,
          "annual_import_volume": 120000,
          "annual_import_value_usd": 11400000,
          "mfn_duty_rate": "2.5%",
          "usmca_duty_rate": "0%",
          "annual_duty_at_mfn": 285000,
          "bill_of_materials": {
            "aluminium_alloy_ingots_canadian": {"cost_per_unit": 32.00, "origin": "Canada", "hs_code": "7601.20"},
            "aluminium_alloy_ingots_russian": {"cost_per_unit": 21.00, "origin": "Russia", "hs_code": "7601.20"},
            "machining_inserts_japan": {"cost_per_unit": 1.50, "origin": "Japan", "hs_code": "8207.70"},
            "paint_and_coating_usa": {"cost_per_unit": 3.00, "origin": "USA", "hs_code": "3208.20"},
            "valve_stems_china": {"cost_per_unit": 0.50, "origin": "China", "hs_code": "8481.80"},
            "direct_labour_mexico": {"cost_per_unit": 12.00},
            "manufacturing_overhead_mexico": {"cost_per_unit": 18.00},
            "profit_margin": {"cost_per_unit": 7.00}
          }
        }
      },
      "task": "Determine whether these wheel rims qualify for USMCA preferential treatment. Identify the applicable rule of origin, perform the qualification analysis, and calculate the duty savings.",
      "evaluation_criteria": [
        {
          "criterion": "rule_of_origin_identification",
          "weight": 0.30,
          "rubric": {
            "pass": "Identifies the USMCA product-specific rule for heading 8708 (or specifically 8708.70) from Annex 4-B. Notes that automotive parts under USMCA have specific rules — heading 8708 typically requires a regional value content (RVC) of 70-75% using the net cost method, or a tariff shift from any other heading. Correctly identifies both the tariff shift and RVC methods as options.",
            "fail": "Cannot identify the applicable rule of origin. Uses a generic 'change in tariff heading' without checking the USMCA Annex. Does not mention the specific RVC requirements for automotive parts under USMCA."
          }
        },
        {
          "criterion": "qualification_analysis",
          "weight": 0.40,
          "rubric": {
            "pass": "Performs both analyses. Tariff shift: the aluminium ingots (7601) shift to wheel rims (8708) — different chapter, so CTH is satisfied. The Japanese machining inserts (8207), Chinese valve stems (8481), and US paint (3208) all shift from different headings. Non-originating materials: Russian aluminium ($21.00) + Japanese inserts ($1.50) + Chinese valve stems ($0.50) = $23.00. RVC calculation (transaction value method): RVC = ((95 - 23) / 95) × 100 = 75.8%. Notes that Canadian aluminium is originating under USMCA cumulation and is excluded from VNM. Concludes the rims qualify under both methods.",
            "fail": "Treats Canadian materials as non-originating (fails to apply USMCA cumulation). Includes labour and overhead in the non-originating material value. Makes mathematical errors in the RVC calculation. Does not perform the actual calculation."
          }
        },
        {
          "criterion": "savings_and_recommendation",
          "weight": 0.30,
          "rubric": {
            "pass": "Calculates annual duty savings: $11,400,000 × 2.5% = $285,000 annual savings. Recommends proceeding with USMCA claims. Notes documentation requirements: the importer can self-certify under USMCA (no prescribed form, but must include nine data elements). Advises obtaining the bill of materials and cost data from the Mexican producer and retaining for 5 years. Mentions that the Mexican producer should be prepared for a potential verification by CBP or Mexican customs.",
            "fail": "Does not calculate the savings. Does not mention the certification requirements. Does not advise on documentation retention. Does not mention the risk of verification."
          }
        }
      ]
    },
    {
      "id": "CTC-006",
      "name": "Handling a CBP CF-28 Request for Information on a routine entry",
      "difficulty": "easy",
      "category": "documentation",
      "context": {
        "situation": "Your customs broker forwarded a CBP CF-28 (Request for Information) received for an entry of stainless steel kitchen sinks from India. CBP is requesting: (1) the manufacturer's name and address, (2) a detailed product description including gauge of steel, dimensions, and mounting type, (3) the country of origin and whether the steel was melted and poured in India, and (4) documentation supporting the declared transaction value of $42 per unit (your supplier is a related party — a subsidiary of your parent company). The entry was filed 45 days ago. The CF-28 gives 30 days to respond.",
        "available_data": {
          "product": "Stainless steel kitchen sinks (18-gauge, undermount, single bowl)",
          "hts_code": "7324.10.0000",
          "origin": "India",
          "supplier": "IndoSteel Home Products Pvt. Ltd. (subsidiary of parent company)",
          "related_party": true,
          "declared_value_per_unit": 42.00,
          "quantity": 3000,
          "total_declared_value": 126000,
          "duty_rate": "3.4%",
          "entry_date": "45 days ago",
          "cf28_response_deadline": "30 days from receipt",
          "steel_origin": "India — melted and poured at Tata Steel Jamshedpur",
          "transfer_pricing_method": "Comparable Uncontrolled Price (CUP)",
          "comparable_market_price_range": "$38-$48 per unit"
        }
      },
      "task": "Draft the response to the CF-28 and explain the significance of each item CBP is requesting. Flag any compliance risks this CF-28 may signal.",
      "evaluation_criteria": [
        {
          "criterion": "cf28_response_quality",
          "weight": 0.35,
          "rubric": {
            "pass": "Drafts a complete, professional response addressing all four CBP requests with specificity: (1) manufacturer details, (2) full product specs (18-gauge 304 stainless steel, specific dimensions, undermount installation), (3) country of origin with steel production details (melted and poured at Tata Steel Jamshedpur — this is relevant for steel-specific origin requirements), (4) related-party valuation support including the CUP analysis showing the $42 price falls within the $38-$48 market range. Response is factual, not defensive.",
            "fail": "Provides vague or incomplete answers. Says 'made in India' without addressing the melted-and-poured question. Does not address the related-party valuation with supporting data. Treats the CF-28 as adversarial rather than informational."
          }
        },
        {
          "criterion": "significance_analysis",
          "weight": 0.35,
          "rubric": {
            "pass": "Explains what the CF-28 signals: CBP is likely verifying (1) whether the sinks are subject to AD/CVD duties (stainless steel sinks from China are under AD/CVD order — CBP is checking that Indian-origin is genuine and not transshipped), (2) whether the related-party price is arm's-length (related-party transactions are standard audit targets), (3) steel origin for potential Section 232 tariff implications. Notes that a CF-28 is informational, not accusatory — but failure to respond completely triggers a CF-29 (Notice of Action) which can change the classification, value, or origin unilaterally.",
            "fail": "Does not explain why CBP asked these specific questions. Does not connect the steel origin question to AD/CVD or Section 232. Does not mention the consequence of inadequate response (CF-29)."
          }
        },
        {
          "criterion": "risk_identification",
          "weight": 0.30,
          "rubric": {
            "pass": "Identifies key risks: (1) if the steel was NOT melted and poured in India, the country of origin for the steel may differ from the country of origin for the finished sink — this affects AD/CVD and Section 232 applicability, (2) the related-party transaction may be scrutinised further if the CUP analysis is weak, (3) this CF-28 may be a precursor to a Focused Assessment if CBP is reviewing the company's import programme broadly. Recommends: respond thoroughly and on time, proactively review other entries of the same product for consistency, and notify legal counsel of the CF-28.",
            "fail": "Does not identify any risks. Treats the CF-28 as routine paperwork. Does not recommend any proactive steps beyond responding to the specific questions."
          }
        }
      ]
    },
    {
      "id": "CTC-007",
      "name": "Simple customs valuation with assists provided to foreign manufacturer",
      "difficulty": "easy",
      "category": "valuation",
      "context": {
        "situation": "Your company imports custom-designed plastic storage containers from a factory in Vietnam. You provided the factory with engineering drawings and a custom mould at no charge. The engineering drawings cost $15,000 to produce (US engineering firm). The mould cost $45,000 (fabricated in Taiwan and shipped directly to the Vietnam factory). The factory's price per container is $2.80 FOB Ho Chi Minh City. You are importing 500,000 containers this year across approximately 20 shipments. Your customs broker has been entering the goods at $2.80 per unit without adding the assist values.",
        "available_data": {
          "product": "Custom-designed plastic storage containers",
          "hts_code": "3924.90.5650",
          "manufacturer": "Vietnam Plastics Co., Ltd",
          "origin": "Vietnam",
          "unit_price_fob": 2.80,
          "annual_volume": 500000,
          "annual_shipments": 20,
          "total_annual_fob_value": 1400000,
          "assists": {
            "engineering_drawings": {"cost": 15000, "produced_in": "USA", "type": "Engineering and design work"},
            "custom_mould": {"cost": 45000, "produced_in": "Taiwan", "shipped_to": "Vietnam factory", "type": "Tool/die/mould"}
          },
          "total_assist_value": 60000,
          "duty_rate": "3.4%",
          "current_annual_duty_paid": 47600,
          "production_life_of_mould": "500,000 units (this year's full order)"
        }
      },
      "task": "Identify the customs valuation error, calculate the correct dutiable value with assists properly allocated, determine the duty underpayment, and recommend corrective action.",
      "evaluation_criteria": [
        {
          "criterion": "assist_identification",
          "weight": 0.30,
          "rubric": {
            "pass": "Correctly identifies both the engineering drawings and the custom mould as dutiable assists under 19 USC § 1401a(h) / 19 CFR § 152.103(d). Explains that the engineering drawings are an assist because they were provided free to the manufacturer for use in producing the imported goods. The mould is an assist of the 'tools, dies, moulds' category. Both must be added to the transaction value. Notes that the engineering work done in the US is still a dutiable assist (unlike the EU, which exempts assists produced in the importing country, the US does not).",
            "fail": "Does not identify both items as assists. Says engineering drawings produced in the US are exempt from US customs valuation (this is an EU rule, not a US rule). Does not recognise that assists must be added to the transaction value."
          }
        },
        {
          "criterion": "correct_calculation",
          "weight": 0.35,
          "rubric": {
            "pass": "Calculates the correct dutiable value: Total assists = $60,000. Prorated across 500,000 units = $0.12 per unit. Adjusted unit value = $2.80 + $0.12 = $2.92. Annual dutiable value = $2.92 × 500,000 = $1,460,000 (plus freight/insurance adjustments). Duty underpayment: ($1,460,000 - $1,400,000) × 3.4% = $2,040. Notes that the mould's $45,000 cost is prorated across its production life (500,000 units), and the engineering cost of $15,000 is similarly prorated across all units produced using those drawings.",
            "fail": "Adds the full $60,000 to the first shipment only (incorrect — assists must be prorated). Makes mathematical errors. Does not prorate the assists across the total production volume."
          }
        },
        {
          "criterion": "corrective_action",
          "weight": 0.35,
          "rubric": {
